import {element as el,request,feedback,number} from './portal-ui.js';
const root=document.querySelector('#workspace'),note=document.querySelector('#workspace-note');
let auth,setup,scoreState,busy=false,epoch=0,expiryTimer;
const field=(parent,label,name,type='text',value='')=>{const wrap=el('label',label),input=el(type==='textarea'?'textarea':'input');input.name=name;if(type==='checkbox')wrap.className='check-label';if(type!=='textarea')input.type=type;input.value=value;wrap.append(input);parent.append(wrap);return input;};
function error(e){feedback(note,e.message||'Chưa thể kết nối máy chủ.',true);if(e.status===401){epoch++;clearTimeout(expiryTimer);auth=null;root.replaceChildren();}}
async function load(){const version=++epoch;auth=await request('/api/v1/auth/session');clearTimeout(expiryTimer);expiryTimer=setTimeout(()=>error({status:401,message:'Phiên đã hết hạn. Vui lòng đăng nhập lại.'}),Math.max(0,new Date(auth.expires_at)-Date.now()));const [config,scores]=await Promise.all([request('/api/v1/judge/research/setup'),request('/api/v1/judge/research/scores')]);if(version!==epoch)return;setup=config;scoreState=scores;root.replaceChildren();feedback(note,config.notice);if(auth.user.role==='ADMIN')await manager(version);if(version===epoch)scoring();}
async function manager(version){const section=el('section','','dashboard-section');section.append(el('h2','Hồ sơ nghiên cứu'),el('p','Tạo hồ sơ mẫu, phiên bản tiêu chí và điều khoản có nguồn. Chỉ công bố thông tin bạn có quyền chia sẻ. Bộ tiêu chí luôn được ghi là bản dự thảo của dự án.'));
const kind=el('select');kind.setAttribute('aria-label','Loại hồ sơ');for(const[v,t]of[['sample','Hũ mẫu & truy xuất'],['rubric','Bộ tiêu chí chấm điểm'],['clause','Điều khoản & nguồn tham khảo']]){const o=el('option',t);o.value=v;kind.append(o);}section.append(kind);const form=el('form','','form-card'),list=el('div');section.append(form,list);root.append(section);let current=null,rows=[];
const build=record=>{current=record;const data=record?.data||{};form.replaceChildren();const title=field(form,'Tên hồ sơ','title','text',data.title||'');title.required=true;title.maxLength=160;
 const fields=kind.value==='sample'?[['Mã mẫu','sample_code'],['Mã hũ','jar_code'],['Mã lô','lot_code'],['Nguồn nguyên liệu (thông tin công khai)','origin','textarea'],['Ghi chép quy trình','process_notes','textarea'],['Ngày sản xuất (nếu có)','production_date','date']]:kind.value==='clause'?[['Mã tiêu chuẩn','standard_code'],['Điều khoản','clause'],['Phiên bản / năm','edition'],['Trích dẫn đầy đủ','citation','textarea'],['Đường dẫn nguồn HTTPS','source_url','url'],['Trích đoạn được phép sử dụng','excerpt','textarea'],['Giới hạn áp dụng','limitation','textarea']]:[];
 const limits={sample_code:50,jar_code:50,lot_code:50,origin:500,process_notes:1500,standard_code:100,clause:100,edition:40,citation:500,source_url:1000,excerpt:4000,limitation:1000};
 for(const[label,name,type]of fields){const input=field(form,label,name,type||'text',data[name]||'');input.required=!['process_notes','production_date'].includes(name);input.maxLength=limits[name]||1000;if(name==='sample_code'){input.minLength=3;input.pattern='[A-Za-z0-9][A-Za-z0-9_-]+';}if(name==='jar_code')input.pattern='[A-Za-z0-9_-]+';}
 if(kind.value==='rubric'){form.append(el('p','Nhập 1–5 tiêu chí. Bỏ trống các dòng không dùng; tổng trọng số phải là 100%. Bản đã lưu được giữ nguyên, sửa bằng cách tạo phiên bản mới.'));for(let i=0;i<5;i++){field(form,`Tiêu chí ${i+1}`,`label_${i}`);field(form,`Trọng số ${i+1} (%)`,`weight_${i}`,'number','20');}}
 const evidenceLabel=el('label','Tài liệu minh chứng (tùy chọn)'),evidence=el('select');evidence.name='evidence_id';const none=el('option','Chưa có minh chứng');none.value='';evidence.append(none);for(const doc of setup.evidence_documents||[]){const option=el('option',`${doc.title} · ${doc.doc_type} · ${doc.evidence_status==='FINAL'?'Đã hoàn tất':'Dự thảo'}`);option.value=doc.id;evidence.append(option);}if(data.evidence_id&&!setup.evidence_documents?.some(x=>x.id===data.evidence_id)){const missing=el('option','Minh chứng ngoài danh sách — chọn lại nếu cần');missing.value=data.evidence_id;evidence.append(missing);}evidence.value=data.evidence_id||'';evidenceLabel.append(evidence);form.append(evidenceLabel,el('p','Chọn từ tối đa 500 tài liệu gần nhất trong cổng giám khảo. Gắn tài liệu không công bố file riêng tư và không xác nhận chất lượng.','small'));
 if(kind.value!=='rubric'){const publicBox=field(form,'Công bố hồ sơ này cho người mở liên kết','published','checkbox');publicBox.checked=!!data.published;}
 if(kind.value==='clause'){const rights=field(form,'Tôi có quyền công bố trích đoạn và đã đối chiếu phiên bản nguồn','rights_confirmed','checkbox');rights.required=true;rights.checked=!!data.rights_confirmed;}
 const actions=el('div','','form-actions'),save=el('button',record?'Lưu thay đổi':'Tạo hồ sơ','button dark');save.type='submit';const fresh=el('button','Hồ sơ mới','text-button');fresh.type='button';fresh.onclick=()=>build(null);actions.append(save,fresh);form.append(actions);
};
const refresh=async()=>{const selectedKind=kind.value;const response=await request('/api/v1/admin/research/'+selectedKind);if(version!==epoch||selectedKind!==kind.value)return;rows=response.items;list.replaceChildren(el('p',`${rows.length} hồ sơ (tối đa 500).`));for(const record of rows){const card=el('article','','library-note');card.append(el('h3',record.title),el('p',`${record.published?'Đang công bố':'Nội bộ'} · Phiên bản ${record.revision}`));const actions=el('div','','form-actions');card.append(actions);if(record.kind!=='rubric'){const edit=el('button','Chỉnh sửa','text-button');edit.onclick=()=>{build(record);form.querySelector('input').focus();};actions.append(edit);}if(record.kind==='sample'&&record.published){const a=el('a','Mở truy xuất ↗');a.href=`truy-xuat.html?sample=${record.public_token}`;const qr=el('a',' Tải mã QR SVG ↓');qr.href=`/api/v1/trace/${record.public_token}/qr.svg`;qr.download=`musuroom-${record.data.jar_code}.svg`;actions.append(a,qr);}list.append(card);}};
kind.onchange=()=>{build(null);refresh().catch(error);};
form.onsubmit=async event=>{event.preventDefault();if(busy)return;const record=current,selectedKind=kind.value;const values=Object.fromEntries(new FormData(form));const data={...values,evidence_id:values.evidence_id||null,published:!!form.elements.published?.checked};if(selectedKind==='sample')data.production_date=values.production_date||null;if(selectedKind==='clause')data.rights_confirmed=form.elements.rights_confirmed.checked;if(selectedKind==='rubric'){data.criteria=[];for(let i=0;i<5;i++){if(values[`label_${i}`]?.trim())data.criteria.push({label:values[`label_${i}`],weight:Number(values[`weight_${i}`])});delete data[`label_${i}`];delete data[`weight_${i}`];}}
 busy=true;for(const control of section.querySelectorAll('input,select,textarea,button'))control.disabled=true;try{await request(`/api/v1/admin/research/${selectedKind}${record?'/'+record.id:''}`,{method:record?'PUT':'POST',csrf:auth.csrf_token,body:{data,...(record?{revision:record.revision}:{})}});if(version!==epoch)return;feedback(note,'Đã lưu hồ sơ.');await load();}catch(e){error(e);}finally{busy=false;for(const control of section.querySelectorAll('input,select,textarea,button'))control.disabled=false;}};
build(null);await refresh();}
function scoring(){const section=el('section','','dashboard-section');root.append(section);section.append(el('h2','Chấm điểm & tổng hợp'),el('p',scoreState.status));if(!setup.samples.length||!setup.rubrics.length){section.append(el('p','Cần có hồ sơ mẫu và bộ tiêu chí trước khi chấm điểm.'));return;}
const form=el('form','','form-card'),sample=el('select'),rubric=el('select'),inputs=el('div'),detail=el('div','','library-note'),revisionNote=el('p','','small'),button=el('button','Lưu điểm của tôi','button dark');revisionNote.setAttribute('role','status');for(const[label,select,rows]of[['Mẫu được chấm',sample,setup.samples],['Bộ tiêu chí',rubric,setup.rubrics]]){const wrap=el('label',label);select.setAttribute('aria-label',label);for(const row of rows){const option=el('option',row.title);option.value=row.id;select.append(option);}wrap.append(select);form.append(wrap);}form.append(detail,revisionNote,inputs,button);let existing;
const render=()=>{const chosen=setup.rubrics.find(x=>x.id===rubric.value),selected=setup.samples.find(x=>x.id===sample.value);existing=scoreState.mine.find(x=>x.rubric_id===rubric.value&&x.sample_id===sample.value);detail.replaceChildren(el('h3',selected.title),el('p',`Mẫu ${selected.data.sample_code} · Hũ ${selected.data.jar_code} · Lô ${selected.data.lot_code} · Phiên bản ${selected.revision}`),el('p',`Nguồn: ${selected.data.origin}`),el('p',`Quy trình: ${selected.data.process_notes||'Chưa có ghi chép'}`));const stale=existing&&existing.sample_revision!==selected.revision;revisionNote.textContent=stale?`Điểm đã lưu dựa trên hồ sơ phiên bản ${existing.sample_revision}. Hãy đọc hồ sơ phiên bản ${selected.revision} và đối chiếu lại trước khi cập nhật.`:existing?`Điểm của bạn: ${number(existing.total)} / 100 · Hồ sơ phiên bản ${selected.revision}.`:'Đọc thông tin mẫu trước khi chấm. Điểm gắn với phiên bản hồ sơ đang hiển thị.';revisionNote.classList.toggle('error',!!stale);button.textContent=stale?'Cập nhật điểm cho hồ sơ hiện tại':'Lưu điểm của tôi';inputs.replaceChildren();chosen.data.criteria.forEach((c,i)=>{const input=field(inputs,`${c.label} (${c.weight}%) — điểm 0–10`,`score_${i}`,'number',existing?.scores[i]??'');input.min='0';input.max='10';input.step='0.1';input.required=true;});};sample.onchange=rubric.onchange=render;render();form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;for(const control of form.querySelectorAll('input,select,button'))control.disabled=true;try{await request('/api/v1/judge/research/scores',{method:'POST',csrf:auth.csrf_token,body:{sample_id:sample.value,sample_revision:setup.samples.find(x=>x.id===sample.value).revision,rubric_id:rubric.value,revision:existing?.revision||0,scores:[...inputs.querySelectorAll('input')].map(x=>Number(x.value))}});feedback(note,'Đã lưu điểm cho phiên bản hồ sơ hiện tại.');await load();}catch(e){error(e);}finally{busy=false;for(const control of form.querySelectorAll('input,select,button'))control.disabled=false;}};section.append(form);
section.append(el('p','Trung bình chỉ tính các phiếu của phiên bản hồ sơ hiện tại. Phiếu cũ được đánh dấu để giám khảo đối chiếu và cập nhật.','small'));const table=el('table'),head=el('tr');for(const t of ['Mẫu / phiên bản','Bộ tiêu chí','Phiếu hiện tại','Phiếu cần đối chiếu lại','Trung bình hiện tại / 100'])head.append(el('th',t));table.append(head);for(const row of scoreState.items){const tr=el('tr');for(const t of [`${setup.samples.find(x=>x.id===row.sample_id)?.title||'Mẫu'} · v${row.current_sample_revision}`,setup.rubrics.find(x=>x.id===row.rubric_id)?.title||'Tiêu chí',row.current_judges,row.stale_judges,number(row.current_mean_total)])tr.append(el('td',t));table.append(tr);}if(!scoreState.items.length)section.append(el('p','Chưa có điểm chấm.'));const wrap=el('div','','table-wrap');wrap.append(table);section.append(wrap);}
load().catch(error);
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});

window.addEventListener('focus',async()=>{if(auth)try{auth=await request('/api/v1/auth/session');}catch(e){error(e);}});
